"""Bounded affinity-supernode search for character-prefix-aware column ordering."""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Optimize DataFrame column permutations while preserving all source cells."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional input frame and the most recently returned row orders."""
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        """Convert a scalar to evaluator text, mapping scalar missing values to empty text."""
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return the exact common-prefix length using binary-search slicing."""
        if left == right:
            return len(left)
        lo, hi = 0, min(len(left), len(right))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if left[:mid] == right[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _score(cls, strings) -> int:
        """Compute ideal Trie reuse as LCP lengths of lexicographically adjacent rows."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            total += len(current) if current == previous else cls._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _positions(columns):
        """Map stringified column labels to their physical positions."""
        positions = {}
        for index, name in enumerate(columns):
            positions.setdefault(str(name), []).append(index)
        return positions

    @classmethod
    def _blocks(cls, width, columns, requested):
        """Build disjoint ordered blocks from valid requested column merges."""
        parent = list(range(width))

        def find(value):
            while parent[value] != value:
                parent[value] = parent[parent[value]]
                value = parent[value]
            return value

        positions = cls._positions(columns)
        for pair in requested or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                a, b = find(left[0]), find(right[0])
                if a != b:
                    parent[b] = a

        groups = {}
        for index in range(width):
            groups.setdefault(find(index), []).append(index)
        return sorted((sorted(group) for group in groups.values()),
                      key=lambda group: group[0])

    @classmethod
    def _repair(cls, width, preference, columns, dependencies, blocks):
        """Topologically repair a preference while enforcing dependencies and merge blocks."""
        positions = cls._positions(columns)
        edges = []
        seen = set()

        def add(left, right):
            if left != right and (left, right) not in seen:
                seen.add((left, right))
                edges.append((left, right))

        for pair in dependencies or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                add(left[0], right[0])

        for block in blocks:
            for left, right in zip(block, block[1:]):
                add(left, right)

        outgoing = [[] for _ in range(width)]
        indegree = [0] * width
        for left, right in edges:
            outgoing[left].append(right)
            indegree[right] += 1

        rank = {value: index for index, value in enumerate(preference)}
        heap = [
            (rank.get(index, width + index), index)
            for index in range(width)
            if indegree[index] == 0
        ]
        heapq.heapify(heap)

        result = []
        while heap:
            _, node = heapq.heappop(heap)
            result.append(node)
            for nxt in outgoing[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    heapq.heappush(heap, (rank.get(nxt, width + nxt), nxt))

        return result if len(result) == width else list(preference)

    @staticmethod
    def _stats(text):
        """Return length-weighted repetition, predecessor repetition, and total mass per column."""
        rows, width = text.shape
        result = []
        for col in range(width):
            counts = {}
            for value in text[:, col]:
                counts[value] = counts.get(value, 0) + 1

            pair = repeat = mass = 0
            for value, count in counts.items():
                length = len(value)
                pair += length * count * (count - 1)
                repeat += length * max(0, count - 1)
                mass += length * count
            result.append((pair, repeat, mass))
        return result

    @staticmethod
    def _affinity(text, left, right):
        """Measure repeated right-field text conditional on equal left-field text."""
        groups = {}
        for row in range(text.shape[0]):
            groups.setdefault(text[row, left], []).append(row)

        total = 0
        for members in groups.values():
            if len(members) < 2:
                continue
            counts = {}
            for row in members:
                value = text[row, right]
                counts[value] = counts.get(value, 0) + 1
            for value, count in counts.items():
                total += len(value) * count * (count - 1)
        return total

    @classmethod
    def _supernode_candidates(cls, text, stats, blocks):
        """Construct two orders from at most ten disjoint high-affinity block packets."""
        if len(blocks) <= 1:
            return [sum(blocks, [])]

        mass = [
            sum(stats[column][0] for column in block)
            for block in blocks
        ]
        active = sorted(
            range(len(blocks)),
            key=lambda i: (-mass[i], blocks[i][0]),
        )[:20]

        affinity = {}
        for left in active:
            for right in active:
                if left == right:
                    continue
                value = 0
                for a in blocks[left][:2]:
                    for b in blocks[right][:2]:
                        value += cls._affinity(text, a, b)
                affinity[left, right] = value

        ranked = []
        for left in active:
            for right in active:
                if left == right:
                    continue
                forward = affinity.get((left, right), 0)
                reverse = affinity.get((right, left), 0)
                reserve = min(forward, reverse)
                ranked.append((-forward - reserve, -forward, left, right))
        ranked.sort()

        chosen = []
        used = set()
        for _, _, left, right in ranked:
            if left in used or right in used:
                continue
            forward = affinity.get((left, right), 0)
            reverse = affinity.get((right, left), 0)
            if reverse > forward:
                left, right = right, left
            chosen.append((left, right))
            used.add(left)
            used.add(right)
            if len(chosen) == 10:
                break

        def construct(reverse_packets):
            """Flatten packets and singleton blocks in deterministic mass order."""
            nodes = []
            paired = set()

            for left, right in chosen:
                if reverse_packets:
                    left, right = right, left
                paired.add(left)
                paired.add(right)
                nodes.append((
                    -(mass[left] + mass[right]),
                    min(blocks[left][0], blocks[right][0]),
                    (left, right),
                ))

            for index in range(len(blocks)):
                if index not in paired:
                    nodes.append((-mass[index], blocks[index][0], (index,)))

            nodes.sort(key=lambda item: (item[0], item[1], item[2]))
            return [
                column
                for _, _, node in nodes
                for block_index in node
                for column in blocks[block_index]
            ]

        return [construct(False), construct(True)]

    @staticmethod
    def _serialize(text, order):
        """Serialize every row by concatenating its cells in the supplied column order."""
        return [
            "".join(text[row, column] for column in order)
            for row in range(text.shape[0])
        ]

    @staticmethod
    def _materialize(df, source, order, serialized):
        """Sort rows by serialized text and materialize an exact cell-preserving permutation."""
        row_order = sorted(range(len(serialized)),
                           key=lambda row: (serialized[row], row))
        values = np.empty(source.shape, dtype=object)
        public_orders = []

        for output_row, source_row in enumerate(row_order):
            values[output_row, :] = [source[source_row, column] for column in order]
            public_orders.append([df.columns[column] for column in order])

        result = pd.DataFrame(
            values,
            index=df.index.take(row_order),
            columns=list(df.columns),
        )
        return result, public_orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        """Evaluate global and affinity-supernode orders, returning the highest exact Trie score."""
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        rows, width = df.shape
        if rows == 0 or width == 0:
            result = df.copy()
            orders = [[] for _ in range(rows)]
            self._last_orders = orders
            return result, orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((rows, width), dtype=object)
        for column in range(width):
            text[:, column] = [
                self._cell_string(value) for value in source[:, column]
            ]

        columns = list(df.columns)
        stats = self._stats(text)
        blocks = self._blocks(width, columns, col_merge)

        global_order = [
            column
            for column, _ in sorted(
                enumerate(stats),
                key=lambda item: (
                    -item[1][0],
                    -item[1][1],
                    -item[1][2],
                    item[0],
                ),
            )
        ]

        preferences = [global_order]
        preferences.extend(self._supernode_candidates(text, stats, blocks))
        preferences = preferences[:3]

        best_score = -1
        best_order = None
        best_serialized = None

        for preference in preferences:
            order = self._repair(
                width,
                preference,
                columns,
                one_way_dep,
                blocks,
            )
            serialized = self._serialize(text, order)
            score = self._score(serialized)
            if score > best_score:
                best_score = score
                best_order = order
                best_serialized = serialized

        result, public_orders = self._materialize(
            df,
            source,
            best_order,
            best_serialized,
        )

        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")

        self._last_orders = public_orders
        return result, public_orders

